var dmList;
const TODAY=new Date();const year=TODAY.getFullYear();let cy=year,cm=TODAY.getMonth(),cd=TODAY.getDate();
const EVENTS={'8-10':['사용자 생일','아쿠아리움'],'8-25':['아쿠아리움'],'9-8':['아쿠아리움'],'9-17':['과제 마감'],'9-29':['술약'],'10-4':['아쿠아리움\n김동현 개새끼야 아쿠아리움 그만적어놔/써놓으면 가주던데'],'10-20':['김동현 생일'],'10-23':['팀플']};
const todayKey=`${TODAY.getMonth()+1}-${TODAY.getDate()}`;EVENTS[todayKey]=[...(EVENTS[todayKey]||[]),'작곡의 이해 과제 마감','아쿠아리움'];
const NOTES=[['장보기','칫솔\n샴푸\n돌돌이\n젤리 딸기맛'],['가사','네가 놓고 간 계절을 아직 입고 있어\n익숙한 골목 끝에서 걸음을 늦춰\n친구라는 말 뒤에 숨겨 둔 마음\n오늘은 너에게 조금 더 가까이'],['반응 좋았던거','코엑스 아쿠아리움(코리도라스)\n와사비? 미친줄\n내 라면\n부산 무슨 국밥집? 잘 모르겠다 같이 가고싶음'],['제목 없음','보고싶어']];
const CHATS=[{title:'짝사랑 고민상담',messages:[['u','친구 좋아하는 것 같은데 친구에서 연인으로 발전하려면 어떻게 해야 돼?'],['a','이미 편한 사이라면 갑자기 관계를 바꾸려 하기보다, 둘만 보내는 시간을 조금씩 늘려 보는 건 어때? 평소와는 조금 다른 관심을 표현하면서 상대의 반응도 살펴봐.'],['u','둘이 밥도 자주 먹고 놀러도 가는데 걔는 그냥 친구라서 그러는 것 같아.'],['a','자주 만난다는 사실만으로 마음을 단정할 수는 없어. “너랑 단둘이 있는 게 좋더라”처럼 네 마음을 조금 보여 줘도 좋아. 부담을 주지 않는 선에서 말이야.'],['u','괜히 말했다가 지금처럼도 못 지내면 어떡해'],['a','그게 제일 걱정되는 거구나. 당장 고백할 필요는 없어. 네 마음과 상대의 편안함을 함께 살피면서 천천히 다가가도 괜찮아.']]},{title:'불루탱 고민상담',messages:[['u','걔가 나보고 블루탱? 닮았다는데 무슨뜻일까'],['a','블루탱은 파란 몸에 노란 꼬리가 있는 물고기야. 영화 속 도리로도 유명해. 장난스럽고 귀여운 인상을 말한 걸 수도 있지만, 어떤 뜻인지는 그 친구에게 물어보는 게 가장 정확해.'],['u','아쿠아리움 갔다가 그랬어'],['a','같이 구경하다가 네 표정이나 움직임이 떠올랐을 수도 있겠다. “어디가 닮았는데?” 하고 가볍게 물어봐도 좋겠어.']]}];
const panel=$('#appPanel');let activeApp='';
function shell(name,dark=false){activeApp=name;$('#home').hidden=true;panel.hidden=false;panel.className='screen apppanel designed '+(dark?'dark':'');panel.innerHTML='<button class="apphome" onclick="closeApp()">‹ 홈</button><div id="appBody"></div>';$('.status').style.color=dark?'white':'#111';$('.homebar').style.background=dark?'white':'#111';return $('#appBody')}
openApp=function(name){if(name==='캘린더')calendar();else if(name==='메모')notes();else if(name==='ChatGPT')chat(0);else if(name==='음악')musicScreen();else if(name==='전화')calls();else if(name==='사진')photoLibrary();else{const b=shell(name);b.innerHTML='<h1>'+name+'</h1><p class="muted">아직 내용이 없는 앱이에요.</p>'}};
closeApp=function(){panel.hidden=true;activeApp='';$('#home').hidden=!unlocked;$('.status').style.color='';$('.homebar').style.background='white'};
function calendar(){const b=shell('캘린더');let start=new Date(cy,cm,1).getDay(),last=new Date(cy,cm+1,0).getDate();b.innerHTML=`<div class="calyear">‹ ${cy}년</div><div class="calhead"><h1>${cm+1}월</h1><button onclick="month(-1)">‹</button><button onclick="month(1)">›</button></div><div class="week">${'일월화수목금토'.split('').map(x=>'<span>'+x+'</span>').join('')}</div><div class="monthgrid">${Array.from({length:start},()=>'<div></div>').join('')}${Array.from({length:last},(_,i)=>{let d=i+1,ev=cy===year&&EVENTS[`${cm+1}-${d}`],today=cy===year&&cm===TODAY.getMonth()&&d===TODAY.getDate();return `<button class="daycell ${cd===d?'selected':''} ${today?'istoday':''}" onclick="cd=${d};calendar()"><span>${d}</span>${ev?'<i></i>':''}</button>`}).join('')}</div><div class="agenda">${(cy===year&&EVENTS[`${cm+1}-${cd}`]||[]).map((s,i)=>`<div class="eventrow" style="border-color:${i%2?'#ff9f0a':'#af52de'}"><span>${s.replaceAll('\n','<br>')}</span><small>종일</small></div>`).join('')||'<p class="muted">일정 없음</p>'}</div><nav class="bottom calbottom"><button onclick="cy=year;cm=TODAY.getMonth();cd=TODAY.getDate();calendar()">오늘</button><button onclick="calendarList()">캘린더</button><button onclick="calendarInbox()">받은 편지함</button></nav>`}
function month(n){cm+=n;if(cm<0){cm=11;cy--}if(cm>11){cm=0;cy++}cd=1;calendar()}
function calendarList(){calendar();$('.agenda').innerHTML='<h3>캘린더</h3><div class="eventrow">✓ 개인 일정 <small>한동민</small></div>'}
function calendarInbox(){calendar();$('.agenda').innerHTML='<p class="muted">새로운 초대가 없습니다.</p>'}
function notes(){const b=shell('메모');panel.classList.add('notes');b.innerHTML=`<div class="notetop">‹ 폴더 <span>선택　⋯</span></div><h1>메모</h1><div class="searchfield">⌕　검색</div><h3>오늘</h3><div class="notelist">${NOTES.map((n,i)=>`<button class="notecard" onclick="note(${i})"><strong>${n[0]}</strong><div><time>${['09:12','08:31','00:47','00:12'][i]}</time> ${n[1].split('\n')[0]}</div></button>`).join('')}</div><nav class="bottom notesbottom"><span>4개의 메모</span><button onclick="newNote()">▢＋</button></nav>`}
function note(i){const b=shell('메모');panel.classList.add('notes');b.innerHTML=`<div class="notetop"><button onclick="notes()">‹ 메모</button><span>⇧　⋯</span></div><p class="notedate">${year}년 ${TODAY.getMonth()+1}월 ${TODAY.getDate()}일</p><h1 contenteditable="true" oninput="NOTES[${i}][0]=this.textContent">${NOTES[i][0]}</h1><div class="notecontent" contenteditable="true" oninput="NOTES[${i}][1]=this.innerText">${NOTES[i][1].replaceAll('\n','<br>')}</div>`}
function newNote(){NOTES.unshift(['제목 없음','']);note(0)}
function chat(i){const b=shell('ChatGPT',true);b.innerHTML=`<header class="chathead"><button onclick="chatHistory()">☰</button><strong>ChatGPT</strong><button onclick="chatHistory()">♧</button></header><div class="chatmessages"><small class="chattitle">${CHATS[i].title}</small>${CHATS[i].messages.map(([r,t])=>`<div class="message ${r==='u'?'usermsg':'assistantmsg'}">${t}</div>`).join('')}<div class="chatactions">▢　♧　♧　♬　⟳</div></div><div class="composer"><textarea placeholder="何でも聞いてください" aria-label="メッセージ" id="chatInput"></textarea><div><button onclick="chatHistory()">＋</button><span>実際のAIには接続していません</span><button onclick="sendChat(${i})">↑</button></div></div>`;$('#chatInput').placeholder='무엇이든 물어보세요';$('#chatInput').setAttribute('aria-label','메시지');$('.composer span').textContent='';$('.chatmessages').scrollTop=0}
function chatHistory(){const b=shell('ChatGPT',true);b.innerHTML=`<h1>ChatGPT</h1><div class="searchfield">⌕　대화 검색</div><h3>최근 대화</h3>${CHATS.map((c,i)=>`<button class="historyrow" onclick="chat(${i})">${c.title}</button>`).join('')}<footer class="account">◉　한동민</footer>`}
function calls(){const b=shell('전화');const ago=new Date(Date.now()-2*60*60*1000);const yest=new Date(TODAY);yest.setDate(yest.getDate()-1);b.innerHTML=`<div class="calltop">편집 <span>＋</span></div><h1>최근 통화</h1><div class="segmented"><button class="on" onclick="calls()">전체</button><button onclick="missed()">부재중 전화</button></div><div id="callrows"><button class="callrow" onclick="callDetail(0)"><span class="callglyph">↗</span><div><strong>김동현</strong><small>휴대전화</small></div><time>${String(ago.getHours()).padStart(2,'0')}:${String(ago.getMinutes()).padStart(2,'0')}</time><span class="info">ⓘ</span></button><button class="callrow" onclick="callDetail(1)"><span class="callglyph">↗</span><div><strong>김동현</strong><small>휴대전화</small></div><time>어제</time><span class="info">ⓘ</span></button></div><nav class="bottom phonebottom"><button onclick="phoneTab('즐겨찾기')">★<small>즐겨찾기</small></button><button class="on" onclick="calls()">◷<small>최근 통화</small></button><button onclick="phoneTab('연락처')">▣<small>연락처</small></button><button onclick="phoneTab('키패드')">⠿<small>키패드</small></button><button onclick="phoneTab('음성 사서함')">◉<small>음성 사서함</small></button></nav>`}
function missed(){calls();$('#callrows').innerHTML='<p class="muted">부재중 전화 없음</p>';document.querySelectorAll('.segmented button').forEach(x=>x.classList.toggle('on'))}
function callDetail(i){const d=new Date();if(i===0)d.setHours(d.getHours()-2);else{d.setDate(d.getDate()-1);d.setHours(23,0,0)}const b=shell('전화');b.innerHTML=`<button class="back" onclick="calls()">‹ 최근 통화</button><div class="contactavatar">김</div><h1 class="center">김동현</h1><div class="contactactions"><button onclick="openApp('문자')">메시지</button><button onclick="callDemo()">통화</button></div><div class="detailcard">${d.getFullYear()}년 ${d.getMonth()+1}월 ${d.getDate()}일<br><br>${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')} 통화 기록</div>`}
function callDemo(){const b=shell('전화',true);b.innerHTML='<h1 class="center">김동현</h1><p class="center muted">실제 통화에 연결되지 않는 시안입니다.</p><button class="endcall" onclick="calls()">종료</button>'}
function phoneTab(t){if(t==='연락처'){calls();$('#callrows').innerHTML='<button class="historyrow" onclick="callDetail(0)">김동현　›</button>';return}if(t==='키패드'){const b=shell('전화');b.innerHTML='<div class="dialnumber" id="dialnumber"></div><div class="dialkeys">'+ '123456789*0#'.split('').map(x=>`<button onclick="document.getElementById('dialnumber').textContent+='${x}'">${x}</button>`).join('')+'</div><button class="dialcall" onclick="callDemo()">통화</button><button class="historyrow" onclick="calls()">‹ 최근 통화</button>';return}calls();$('#callrows').innerHTML='<p class="muted">'+t+' 없음</p>'}
$('.calendar-widget').style.cursor='pointer';$('.calendar-widget').onclick=()=>openApp('캘린더');

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function relativeDate(months=0,days=0,h=12,min=0){const d=new Date();const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()-months);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));d.setDate(d.getDate()-days);d.setHours(h,min,0,0);return d}
const longDate=d=>d.toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'});
const clock=d=>d.toLocaleTimeString('ko-KR',{hour:'numeric',minute:'2-digit',hour12:true});
const phoneIcon='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M5.1 2.4 2.8 4.1c-2 2 1.4 8.7 5 12.3s10.3 7 12.3 5l1.7-2.3c.5-.7.3-1.5-.4-1.9l-4-2.3c-.6-.3-1.2-.2-1.6.3l-1.4 1.7c-2.5-1-6.3-4.8-7.3-7.3L8.8 8c.5-.4.6-1 .3-1.6L6.8 2.8c-.4-.7-1.2-.9-1.7-.4Z"/></svg>';
const SMS=[{name:'좋아해',date:relativeDate(3,0,21,32),messages:[['in','나 카톡이 안 보내지네',relativeDate(3,0,21,30)],['in','여기 주차장 앞에 서있음',relativeDate(3,0,21,30)],['out','ㅇㅇ금방감',relativeDate(3,0,21,32)]]},{name:'CJ대한통운',date:relativeDate(2,0,14,18),messages:[['in','[Web발신][CJ대한통운_배송완료]\n일요일에도 신속하게!!\n모두를 위한 매일매일 배송\n\nCJ대한통운 매일오네(O-NE)\n\n고객님의 상품이 배송 완료되었습니다.\nㆍ상품명 : [인테리어 소품] LP 플레이어 세트\nㆍ인수자(위탁장소) : 한동민\nㆍ운송장번호 : 00000000000\n\n모두를 위한 단 하나의 배송!\nCJ대한통운 오네',relativeDate(2,0,14,18)]]},{name:'카카오',date:relativeDate(0,2,16,4),messages:[['in','[Web발신]\n[카카오] 인증번호 [482913]를 입력해 주세요. 타인에게 인증번호를 알려주지 마세요.',relativeDate(0,2,16,4)]]},{name:'한국대학교',date:relativeDate(0,9,10,22),messages:[['in','[Web발신]\n한국대학교 통합로그인 인증번호는 [706284]입니다. 3분 이내에 입력해 주세요.',relativeDate(0,9,10,22)]]},{name:'본인확인',date:relativeDate(1,0,18,42),messages:[['in','[Web발신]\n본인확인 인증번호 [391057]\n인증번호를 입력해 주세요.',relativeDate(1,0,18,42)]]}];
function messages(){const b=shell('문자');panel.classList.add('sms');const order=SMS.map((s,i)=>({...s,i})).sort((a,b)=>b.date-a.date);b.innerHTML=`<div class="ios-top"><button onclick="messages()">필터</button><span>•••　▢＋</span></div><h1>메시지</h1><input class="xsearch" placeholder="검색" oninput="filterSMS(this.value)"><div id="smslist">${order.map(s=>`<button class="smsrow" data-text="${s.name}" onclick="smsThread(${s.i})"><div class="contact-avatar">♙</div><div><strong>${s.name}</strong><time>${s.date.toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'})}　›</time><p>${esc(s.messages.at(-1)[1]).slice(0,86)}</p></div></button>`).join('')}</div><p class="smsfoot">iCloud에 동기화됨</p>`}
function filterSMS(v){document.querySelectorAll('.smsrow').forEach(r=>r.hidden=!r.dataset.text.includes(v))}
function smsThread(i){const s=SMS[i],b=shell('문자');panel.classList.add('sms');b.innerHTML=`<header class="smshead"><button onclick="messages()">‹ 메시지</button><div class="contact-avatar">♙</div><strong>${s.name} ›</strong></header><div class="smsthread"><div class="smsdate">문자 메시지 · SMS<br>${longDate(s.date)}</div>${s.messages.map(([r,t,d])=>`<div class="smsmsg ${r}"><div>${esc(t).replaceAll('\n','<br>')}</div><small>${clock(d)}</small></div>`).join('')}</div><div class="smscompose"><button>＋</button><input id="smsInput" placeholder="문자 메시지"><button aria-label="보내기" onclick="sendSMS(${i})">↑</button></div>`}
function sendSMS(i){const v=$('#smsInput').value.trim();if(!v)return;SMS[i].messages.push(['out',v,new Date()]);smsThread(i);$('.smsthread').scrollTop=99999}
