let lastQuery='';
function safariBar(){return `<div class="safaribottom"><form onsubmit="event.preventDefault();searchWeb(this.q.value)"><span>aA</span><input name="q" value="${esc(lastQuery)}" placeholder="검색 또는 웹 사이트 이름"><span>⟳</span></form><nav><button onclick="safari()">‹</button><button onclick="lastQuery&&searchWeb(lastQuery)">›</button><button onclick="safariNotice()">↥</button><button onclick="safariHistory()">▤</button><button onclick="safari()">▢</button></nav></div>`}
function safari(){const b=shell('인터넷');panel.classList.add('safari');lastQuery='';b.innerHTML=`<h1>즐겨찾기</h1><div class="favorites"><button onclick="searchWeb('Apple')"><span style="background:#444">●</span>Apple</button><button onclick="searchWeb('Google')"><span style="background:#fff;color:#4285f4">G</span>Google</button><button onclick="searchWeb('NAVER')"><span style="background:#03c75a">N</span>NAVER</button></div><h2>개인정보 보호 리포트</h2><div class="privacybox">◈　Safari는 개인 정보를 보호하며<br>　　안전한 웹 탐색을 도와줍니다.</div><div class="historyheading"><h2>방문 기록</h2><button onclick="safariHistory()">모두 보기</button></div>${historyRows()}${safariBar()}`}
function historyRows(){return [...WEBHISTORY].sort((a,b)=>b[1]-a[1]||b[2]-a[2]).map(([q,m,d])=>`<button class="webhistory" onclick="searchWeb('${q}')"><span class="webglass">⌕</span><div>${q}<small>${year}년 ${m}월 ${d}일</small></div><span>↗</span></button>`).join('')}
function safariHistory(){const b=shell('인터넷');panel.classList.add('safari');b.innerHTML=`<div class="ios-top"><button onclick="safari()">‹ Safari</button><b>방문 기록</b><span>◷</span></div><h1>방문 기록</h1>${historyRows()}${safariBar()}`}
function searchWeb(q){q=q.trim();if(!q)return;lastQuery=q;const b=shell('인터넷');panel.classList.add('safari','webresults');const results=RESULTS[q]||[[q+' 검색 결과','검색 미리보기','아래 버튼을 누르면 실제 웹 검색으로 연결됩니다.']];b.innerHTML=`<div class="googleword"><i>G</i><i>o</i><i>o</i><i>g</i><i>l</i><i>e</i></div><form class="webquery" onsubmit="event.preventDefault();searchWeb(this.q.value)"><input name="q" value="${esc(q)}"><button>⌕</button></form><div class="webtabs">전체　이미지　동영상　쇼핑　뉴스</div><div class="webdemo">캐릭터용 검색 결과 재현 · 실시간 검색 아님</div>${results.map(([t,site,desc])=>`<article class="webresult"><small>◎　${site}</small><h2><a href="https://www.google.com/search?q=${encodeURIComponent(t)}" target="_blank" rel="noopener">${t}</a></h2><p>${desc}</p></article>`).join('')}<a class="realweb" target="_blank" rel="noopener" href="https://www.google.com/search?q=${encodeURIComponent(q)}">실제 Google 검색 결과 보기 ↗</a>${safariBar()}`}
function safariNotice(){const el=document.createElement('div');el.className='xtoast';el.textContent='휴대폰 안에 구현된 Safari 시안입니다.';panel.append(el);setTimeout(()=>el.remove(),2200)}
const CONTACTS=['엄마','아빠','펌킨박','상혁이형','똥개의 일상','좋아해','돼지','한승훈','여동생'];
const CALLS=[{name:'좋아해',date:new Date(Date.now()-5*60000),missed:true},{name:'좋아해',date:new Date(Date.now()-2*3600000)},{name:'좋아해',date:relativeDate(0,1,23,0)},{name:'돼지',date:relativeDate(0,1,19,18),missed:true},{name:'070-0000-0142',date:relativeDate(0,3,13,12),missed:true,spam:true},{name:'010-0000-0286',date:relativeDate(0,5,16,42),missed:true},{name:'돼지',date:relativeDate(0,7,20,3),missed:true},{name:'02-000-0317',date:relativeDate(0,10,11,7),spam:true},{name:'010-0000-0469',date:relativeDate(0,14,18,24),missed:true}];
function callDate(d){const now=new Date(),a=new Date(now.getFullYear(),now.getMonth(),now.getDate()),b=new Date(d.getFullYear(),d.getMonth(),d.getDate()),days=Math.round((a-b)/86400000);if(days===0){const mins=Math.floor((now-d)/60000);if(mins<60)return mins+'분 전';return clock(d)}if(days===1)return '어제';if(days===7)return '일주일 전';return d.toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'})}
function phoneNav(tab){return `<nav class="bottom phonebottom">${[['즐겨찾기','★','phoneFavorites()'],['최근 통화','◷','calls()'],['연락처','♙','phoneContacts()'],['키패드','⠿','phoneKeypad()']].map(([n,i,fn])=>`<button class="${tab===n?'on':''}" onclick="${fn}">${i}<small>${n}</small></button>`).join('')}</nav>`}
function calls(only=false){const b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<div class="calltop">편집 <span>＋</span></div><h1>최근 통화</h1><div class="segmented"><button class="${only?'':'on'}" onclick="calls()">전체</button><button class="${only?'on':''}" onclick="calls(true)">부재중 전화</button></div><div>${CALLS.map((c,i)=>only&&!c.missed?'':`<div class="callrow ${c.missed?'missedrow':''}"><span class="callglyph">${c.missed?'↙':'↗'}</span><button class="callidentity" onclick="startCall('${c.name}')"><strong>${c.name}</strong><small>${c.spam?'스팸 의심 · 예시 번호':'휴대전화'}</small></button><time>${callDate(c.date)}</time><button class="info" onclick="callInfo(${i})">ⓘ</button></div>`).join('')}</div>${phoneNav('최근 통화')}`}
function missed(){calls(true)}
function callInfo(i){const c=CALLS[i],b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<button class="xback" onclick="calls()">‹ 최근 통화</button><div class="contacthero"><div class="contact-avatar">${c.name[0]}</div><h1>${c.name}</h1></div><div class="contactactions"><button onclick="startCall('${c.name}')">${phoneIcon}통화</button><button onclick="smsThread(0)">▢<br>메시지</button></div><div class="detailcard">${longDate(c.date)}<br>${clock(c.date)}<br>${c.missed?'부재중 전화':'발신 통화'}</div>${phoneNav('최근 통화')}`}
function phoneFavorites(){const b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<div class="calltop">＋ <span>편집</span></div><h1>즐겨찾기</h1>${['좋아해','엄마'].map(n=>`<button class="favoritecontact" onclick="startCall('${n}')"><span class="contact-avatar">${n[0]}</span><div><strong>${n}</strong><small>☎ 휴대전화</small></div><span class="info">ⓘ</span></button>`).join('')}${phoneNav('즐겨찾기')}`}
function phoneContacts(){const b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<h1>연락처</h1><input class="xsearch" placeholder="검색" oninput="document.querySelectorAll('.contactline').forEach(r=>r.hidden=!r.textContent.includes(this.value))"><div class="mycard"><div class="contact-avatar">동</div><span><b>한동민</b><small>내 카드</small></span></div>${[...CONTACTS].sort((a,b)=>a.localeCompare(b,'ko')).map(n=>`<button class="contactline" onclick="contactPage('${n}')">${n}</button>`).join('')}${phoneNav('연락처')}`}
function contactPage(n){const b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<button class="xback" onclick="phoneContacts()">‹ 연락처</button><div class="contacthero"><div class="contact-avatar">${n[0]}</div><h1>${n}</h1></div><div class="contactactions"><button onclick="startCall('${n}')">${phoneIcon}통화</button>${n==='좋아해'?'<button onclick="smsThread(0)">▢<br>메시지</button>':''}</div><div class="detailcard">휴대전화<br><span class="muted">등록된 번호는 비공개입니다.</span></div>${phoneNav('연락처')}`}
let dialNumber='';
function phoneKeypad(){const b=shell('전화');panel.classList.add('phoneapp');b.innerHTML=`<div class="dialdisplay" id="dialDisplay">${esc(dialNumber)}</div><div class="realkeypad">${['1','2','3','4','5','6','7','8','9','*','0','#'].map((n,i)=>`<button onclick="dialNumber+='${n}';$('#dialDisplay').textContent=dialNumber">${n}<small>${['','ABC','DEF','GHI','JKL','MNO','PQRS','TUV','WXYZ','','＋',''][i]}</small></button>`).join('')}</div><div class="dialactions"><span></span><button class="greencall" aria-label="좋아해에게 전화" onclick="startCall('좋아해')">${phoneIcon}</button><button class="dialdelete" onclick="dialNumber=dialNumber.slice(0,-1);$('#dialDisplay').textContent=dialNumber">⌫</button></div><small class="dialhint">통화 버튼을 누르면 좋아해에게 연결됩니다.</small>${phoneNav('키패드')}`}
let callTimer=null,callSeconds=0;
function startCall(name='좋아해'){clearInterval(callTimer);callSeconds=0;const b=shell('전화',true);panel.classList.add('incall');b.innerHTML=`<div class="callperson">${esc(name)}</div><div class="callstate" id="callState">전화 거는 중…</div><div class="callportrait">${esc(name[0])}</div><div class="callcaption" id="callCaption"></div><div class="calloptions">${[['음소거','♩'],['키패드','⠿'],['스피커','◖'],['통화 추가','＋'],['FaceTime','▣'],['연락처','♙']].map(([t,i])=>`<button onclick="this.classList.toggle('enabled')"><span>${i}</span>${t}</button>`).join('')}</div><button class="endcall" aria-label="통화 종료" onclick="endCall()">${phoneIcon}</button><small class="callmock">음성 연결 없는 통화 시뮬레이션</small>`;callTimer=setInterval(()=>{if(!$('#callState')){clearInterval(callTimer);return}callSeconds++;$('#callState').textContent=Math.floor(callSeconds/60)+':'+String(callSeconds%60).padStart(2,'0');},1000);CALLS.unshift({name,date:new Date(),missed:false})}
function endCall(){clearInterval(callTimer);calls()}
const prevOpenApp=openApp;openApp=function(n){clearInterval(callTimer);if(n==='문자')messages();else if(n==='인터넷'||n==='Safari'||n==='사파리')safari();else if(n==='전화')calls();else prevOpenApp(n)};
const prevCloseApp=closeApp;closeApp=function(){clearInterval(callTimer);prevCloseApp()};
phoneTab=function(t){if(t==='즐겨찾기')phoneFavorites();else if(t==='연락처')phoneContacts();else if(t==='키패드')phoneKeypad();else calls()};


const PHOTO='assets/images/698070a68316c6.jpg';
const ico=(n)=>{const p={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',dm:'<path d="m22 2-7 20-4-9-9-4zM11 13 22 2"/>',heart:'<path d="M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-5 4 0 10 8 16 8-6 13-12 8-16Z"/>',comment:'<path d="M21 11a9 9 0 1 0-5 8l5 2-1-6z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',grid:'<rect x="3" y="3" width="18" height="18"/><path d="M9 3v18M15 3v18M3 9h18M3 15h18"/>',reels:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M3 9h18M8 3l4 6M15 3l4 6m-9 4 6 3-6 3z"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4z"/>',plus:'<rect x="3" y="3" width="18" height="18" rx="5"/><path d="M12 7v10M7 12h10"/>',back:'<path d="m15 4-8 8 8 8"/>',chat:'<path d="M21 11a9 8 0 1 0-13 7l-3 4 7-3a9 8 0 0 0 9-8z"/>',gear:'<circle cx="12" cy="12" r="4"/><path d="m12 2 2 3 4-1 1 4 3 2-2 4 1 4-4 1-3 3-3-2-4 1-1-4-3-3 2-3-1-4 4-1z"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[n]||p.profile}</svg>`};
const blank=(cls='')=>`<span class="blank-avatar ${cls}">${ico('profile')}</span>`;
let NAVSTACK=[],lastApp='',restoring=false;
function setAppStatus(on,dark=false){$('.phone').classList.toggle('in-app',on);$('#statusTime').hidden=on;$('#statusHome').hidden=!on;$('.status').style.color=on?(dark?'#fff':'#111'):'';$('.homebar').style.background=on&&!dark?'#111':'#fff'}
shell=function(name,dark=false){if(!restoring&&name===lastApp&&$('#appBody'))NAVSTACK.push({html:panel.innerHTML,cls:panel.className,scroll:$('#appBody').scrollTop,dark:panel.classList.contains('dark')});else if(name!==lastApp)NAVSTACK=[];lastApp=name;activeApp=name;$('#home').hidden=true;panel.hidden=false;panel.className='screen apppanel designed '+(dark?'dark':'');panel.innerHTML='<div class="app-navigation"><button aria-label="뒤로가기" onclick="appBack()">'+ico('back')+'<span>뒤로</span></button><small>'+esc(name)+'</small></div><div id="appViewport"><div id="appBody"></div></div>';setAppStatus(true,dark);panel.animate([{opacity:.65,transform:'translateY(12px) scale(.975)'},{opacity:1,transform:'none'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'});return $('#appBody')};
function appBack(){clearInterval(callTimer);if(!NAVSTACK.length){closeApp();return}const s=NAVSTACK.pop();restoring=true;panel.innerHTML=s.html;panel.className=s.cls;$('#appBody').scrollTop=s.scroll;setAppStatus(true,s.dark);restoring=false;panel.animate([{opacity:.5,transform:'translateX(-12px)'},{opacity:1,transform:'none'}],{duration:180})}
closeApp=function(){clearInterval(callTimer);NAVSTACK=[];lastApp='';activeApp='';panel.hidden=true;$('#home').hidden=!unlocked;setAppStatus(false);if(unlocked)$('#home').animate([{opacity:.4,transform:'scale(1.045)'},{opacity:1,transform:'scale(1)'}],{duration:280,easing:'ease-out'})};
const NOTE_DAYS=[1,4,7,13,2];NOTES.push(['알바','매주 목금 5시 반 잊지말기']);
function nd(i){return relativeDate(0,NOTE_DAYS[i]??0, [9,22,0,23,18][i]??12, [12,31,47,12,5][i]??0)}
notes=function(){const b=shell('메모');panel.classList.add('notes');const sorted=NOTES.map((n,i)=>({n,i,d:nd(i)})).sort((a,b)=>b.d-a.d);b.innerHTML='<div class="notetop">‹ 폴더 <span>선택　⋯</span></div><h1>메모</h1><div class="searchfield">⌕　검색</div><div class="notelist">'+sorted.map(({n,i,d})=>`<button class="notecard" onclick="note(${i})"><strong>${esc(n[0])}</strong><div><time>${d.toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'})}</time> ${esc(n[1].split('\n')[0])}</div></button>`).join('')+`</div><nav class="bottom notesbottom"><span>${NOTES.length}개의 메모</span><button onclick="newNote()">${ico('plus')}</button></nav>`};
note=function(i){const b=shell('메모');panel.classList.add('notes');b.innerHTML=`<div class="notetop"><button onclick="notes()">‹ 메모</button><span>⇧　⋯</span></div><p class="notedate">${longDate(nd(i))} ${clock(nd(i))}</p><h1 contenteditable="true" oninput="NOTES[${i}][0]=this.textContent">${esc(NOTES[i][0])}</h1><div class="notecontent" contenteditable="true" oninput="NOTES[${i}][1]=this.innerText">${esc(NOTES[i][1]).replaceAll('\n','<br>')}</div>`};
EVENTS['10-4']=EVENTS['10-4'].map(s=>s.replace('/','\n'));
const DEFAULT_DM=[{name:'kdhxxn_',text:'나 갸라도스 잡았어',time:'2시간 전',read:true,out:false},{name:'myeongmyeong',text:'이런 릴스 보내지 마라',time:'어제',read:true,out:false},{name:'jisoo__',text:'오빠 여기 어디에요?ㅎㅎ',time:'일주일 전',read:false,out:false},{name:'minsuuu',text:'10분이면 가요',time:'일주일 전',read:true,out:true}];
const DEFAULT_KAKAO=[{name:'좋아해',text:'너 어딘데',time:'방금',read:false},{name:'똥개의 일상',text:'너 폰 잃어버렸냐?',time:'3분 전',read:false},{name:'펌킨박',text:'너 동현이랑 수업 쨌냐?',time:'11분 전',read:false},{name:'폐급 모임',text:'아니 과제 어제까지였다고?',time:'5시간 전',read:true},{name:'실음과 23학번 공지방',text:'공지 확인해주세요',time:'어제 19:28',read:true},{name:'상혁이형',text:'걔 잡아둬',time:'어제',read:true},{name:'돼지',text:'동민이형 제발 제 잠바 돌려줘요',time:'어제',read:true},{name:'실음과 23 박연주',text:'동민아 내일 시간 돼?',time:'5일 전',read:false}];
let social;try{social=JSON.parse(localStorage.getItem('dongmin-phone-public-v1'))}catch(e){}if(!social)social={dm:DEFAULT_DM,kakao:DEFAULT_KAKAO,liked:false};
for(const type of ['dm','kakao'])for(const c of social[type])if(!c.messages)c.messages=[{out:!!c.out,text:c.text,time:c.time}];
function saveSocial(){try{localStorage.setItem('dongmin-phone-public-v1',JSON.stringify(social))}catch(e){}}
function igNav(active='home'){return `<nav class="igbottom fixedbar">${[['home','igHome()'],['search','igExplore()'],['plus','igCreate()'],['reels','igReels()'],['profile','igProfile()']].map(([n,fn])=>`<button aria-label="${n}" class="${active===n?'selected':''}" onclick="${fn}">${ico(n)}</button>`).join('')}</nav>`}
function igShell(){const b=shell('인스타');panel.classList.add('instagram');return b}
function igHome(){const b=igShell();b.innerHTML=`<header class="igheader"><strong>Instagram</strong><button onclick="igActivity()" aria-label="알림">${ico('heart')}</button><button onclick="dmList()" aria-label="메시지">${ico('dm')}${social.dm.some(c=>!c.read)?'<i class="reddot"></i>':''}</button></header><div class="stories">${['내 스토리','kdhxxn_','myeongmyeong','jisoo__','minsuuu'].map((n,i)=>`<button onclick="${i?'igStory('+i+')':'igProfile()'}"><span class="storyring ${i?'':'mine'}">${blank()}</span><small>${n}</small></button>`).join('')}</div><div class="postuser">${blank()}<strong>kdhxxn_</strong><span>•••</span></div><img class="aquarium-post" src="${PHOTO}" alt="아쿠아리움 수조 앞에 서 있는 사람"><div class="posttools"><button class="${social.liked?'liked':''}" onclick="toggleLike()" aria-label="좋아요">${ico('heart')}</button><button onclick="igComments()" aria-label="댓글">${ico('comment')}</button><button onclick="dmList()" aria-label="공유">${ico('dm')}</button><button class="savepost" onclick="this.classList.toggle('selected')" aria-label="저장">${ico('bookmark')}</button></div><div class="postcopy"><b>좋아요 ${social.liked?33:32}개</b><button onclick="igComments()">댓글 3개 모두 보기</button><p><b>hxxnd.min</b> 누구랑 갔냐 <small>이틀 전</small></p><small>10월 23일</small></div>${igNav()}`}
function toggleLike(){social.liked=!social.liked;saveSocial();const pos=$('#appBody').scrollTop;igHome();NAVSTACK.pop();$('#appBody').scrollTop=pos}
function igProfile(){const b=igShell();b.innerHTML=`<header class="igheader"><b>hxxnd.min</b><button onclick="igCreate()">${ico('plus')}</button><button onclick="igSettings()">☰</button></header><div class="igstats">${blank('large')}<span><b>0</b>게시물</span><span><b>332</b>팔로워</span><span><b>174</b>팔로잉</span></div><div class="profileedit"><button onclick="igSettings()">프로필 편집</button><button onclick="igShareProfile()">프로필 공유</button></div><div class="profiletabs">${ico('grid')}${ico('profile')}</div><div class="emptypost">${ico('plus')}<h2>아직 게시물 없음</h2></div>${igNav('profile')}`}
function igComments(){const b=igShell();b.innerHTML=`<h2 class="center">댓글</h2><div class="igcomment">${blank()}<div><b>hxxnd.min <small>이틀 전</small></b><p>누구랑 갔냐</p><small>답글 달기</small></div>${ico('heart')}</div><p class="quiet">나머지 2개 댓글의 내용은 아직 설정되지 않았습니다.</p>${igNav()}`}
function igStory(i){const b=igShell();panel.classList.add('igstory');setAppStatus(true,true);b.innerHTML=`<div class="storyprogress"></div><header class="storytitle">${blank()}<b>${i===0?'hxxnd.min':['','kdhxxn_','myeongmyeong','jisoo__','minsuuu'][i]}</b><button onclick="appBack()">×</button></header><div class="storyempty">${i===0?'하이라이트':'스토리'}<small>추가할 콘텐츠가 없습니다.</small></div><div class="storyreply"><input placeholder="메시지 보내기" aria-label="스토리 답장"><button onclick="dmList()">${ico('dm')}</button></div>`}
function igExplore(){const b=igShell();b.innerHTML=`<h1>검색</h1><input class="xsearch" placeholder="검색" oninput="$('#igsearchresult').hidden=!this.value"><button id="igsearchresult" class="historyrow" hidden onclick="dmList()">kdhxxn_</button>${igNav('search')}`}
function igCreate(){const b=igShell();b.innerHTML='<h2>새 게시물</h2><p class="quiet">아직 추가한 사진이 없습니다.</p>'+igNav('plus')}
function igReels(){const b=igShell();b.innerHTML='<h2>릴스</h2><p class="quiet">등록된 릴스가 없습니다.</p>'+igNav('reels')}
function igActivity(){const b=igShell();b.innerHTML='<h1>알림</h1><p class="quiet">새 알림이 없습니다.</p>'+igNav()}
