function igShareProfile(){const b=igShell();b.innerHTML='<h2>프로필 공유</h2><div class="shareprofile">@hxxnd.min</div>'+igNav('profile')}
function socialRow(type,c,i){const m=c.messages.at(-1)||{text:"",time:"",out:false};return `<button class="socialrow ${c.read?'':'unread'}" data-name="${esc(c.name)}" onclick="socialThread('${type}',${i})">${blank()}<div><strong>${esc(c.name)}</strong><p>${m.out?'회원님: ':''}${esc(m.text)}</p></div><aside><time>${esc(m.time)}</time>${!c.read?'<span class="unreadbadge">'+(type==='kakao'?'1':'')+'</span>':''}</aside></button>`}
function filterSocial(v){document.querySelectorAll('.socialrow').forEach(r=>r.hidden=!r.dataset.name.includes(v))}
function kakaoNav(tab){return `<nav class="kakaobottom fixedbar">${[['친구','profile','kakaoFriends()'],['채팅','chat','kakaoChats()'],['오픈채팅','comment','kakaoOpen()'],['더보기','grid','kakaoMore()']].map(([t,i,fn])=>`<button class="${t===tab?'selected':''}" onclick="${fn}">${ico(i)}<small>${t}</small>${t==='채팅'&&social.kakao.some(c=>!c.read)?'<span class="navbadge">'+social.kakao.filter(c=>!c.read).length+'</span>':''}</button>`).join('')}</nav>`}
function kShell(){const b=shell('카카오톡');panel.classList.add('kakaoapp');return b}
function kHeading(t){return `<header class="kheading"><h1>${t}</h1><button onclick="kakaoSearch()">${ico('search')}</button><button onclick="kakaoMore()">${ico('gear')}</button></header>`}
function kakaoFriends(){const b=kShell();b.innerHTML=kHeading('친구')+`<div class="kmyprofile">${blank()}<b>한동민</b></div><div class="friendcount">친구 ${CONTACTS.length}</div>`+CONTACTS.map(n=>`<button class="kfriend" onclick="kakaoContact('${n}')">${blank()}<b>${n}</b></button>`).join('')+kakaoNav('친구')}
function kakaoContact(n){let i=social.kakao.findIndex(c=>c.name===n);if(i<0){i=social.kakao.length;social.kakao.push({name:n,text:'',time:'',read:true,messages:[]});saveSocial()}socialThread('kakao',i)}
function kakaoSearch(){const b=kShell();b.innerHTML='<h1>검색</h1><input class="xsearch" placeholder="이름 검색" oninput="filterSocial(this.value)">'+social.kakao.map((c,i)=>socialRow('kakao',c,i)).join('')}
function kakaoOpen(){const b=kShell();b.innerHTML=kHeading('오픈채팅')+'<p class="quiet">참여 중인 오픈채팅이 없습니다.</p>'+kakaoNav('오픈채팅')}
function kakaoMore(){const b=kShell();b.innerHTML=kHeading('더보기')+'<div class="kmyprofile">'+blank()+'<b>한동민</b></div><div class="detailcard">한국대학교 실용음악과</div>'+kakaoNav('더보기')}
function socialThread(type,i){const c=social[type][i];c.read=true;saveSocial();const b=type==='dm'?igShell():kShell();panel.classList.add('socialthread',type==='dm'?'dmthread':'kthread');b.innerHTML=`<header class="threadhead"><button onclick="${type==='dm'?'dmList()':'kakaoChats()'}">${ico('back')}</button>${blank()}<strong>${esc(c.name)}</strong><span>${type==='dm'?'⌕　⋯':'☰'}</span></header><div class="socialmessages" id="socialMessages">${c.messages.map((m,j)=>`<div class="socialbubble ${m.out?'out':'in'}">${!m.out&&type==='kakao'?blank():''}<div><p>${esc(m.text).replaceAll('\n','<br>')}</p><small>${esc(m.time)}${m.out&&type==='dm'&&j===c.messages.length-1&&c.out&&c.read?' · 읽음':''}</small></div></div>`).join('')}</div><form class="socialcompose" onsubmit="event.preventDefault();socialSend('${type}',${i})"><button type="button" aria-label="첨부">＋</button><input id="socialInput" autocomplete="off" placeholder="${type==='dm'?'메시지 보내기…':'메시지 입력'}" aria-label="메시지"><button type="submit">${type==='dm'?'보내기':'전송'}</button></form>`;$('#socialMessages').scrollTop=999999}
function socialSend(type,i){const input=$('#socialInput'),text=input.value.trim();if(!text)return;const c=social[type][i];c.messages.push({out:true,text,time:clock(new Date())});c.read=true;saveSocial();socialThread(type,i);NAVSTACK.pop()}
safari=function(){lastQuery='';const b=shell('인터넷');panel.classList.add('safari');b.innerHTML=`<h1>즐겨찾기</h1><div class="favorites"><button onclick="naverHome()"><span style="background:#03c75a">N</span>NAVER</button></div><h2>개인정보 보호 리포트</h2><div class="privacybox">◈　Safari는 웹 탐색 중 개인 정보를 보호합니다.</div>${safariBar()}`};
function naverHome(){lastQuery='naver.com';const b=shell('인터넷');panel.classList.add('safari','naver');b.innerHTML=`<header class="naverheader"><span>☰</span><b>NAVER</b><span>▢</span></header><button class="naversearch" onclick="naverRecent()"><b>N</b><span>검색어를 입력해주세요</span>${ico('search')}</button><div class="naverlinks">메일　카페　블로그　쇼핑　뉴스</div><div class="navercard"><b>서울특별시 강서구</b><p>관심 있는 정보를 검색해 보세요.</p></div><div class="naverwelcome"><strong>오늘도, 네이버와 함께</strong><p>검색창을 누르면 최근 검색어를 볼 수 있어요.</p></div>${safariBar()}`}
function naverRecent(){const b=shell('인터넷');panel.classList.add('safari','naver');b.innerHTML=`<form class="naversearch" onsubmit="event.preventDefault();naverResults(this.q.value)"><b>N</b><input name="q" placeholder="검색어를 입력해주세요" autocomplete="off"><button>${ico('search')}</button></form><h3>최근 검색어</h3>${[...WEBHISTORY].sort((a,b)=>b[1]-a[1]||b[2]-a[2]).map(([q,m,d])=>`<button class="naverrecent" onclick="naverResults('${q}')"><span>◷</span><b>${q}</b><small>${m}.${String(d).padStart(2,'0')}</small><span>↖</span></button>`).join('')}${safariBar()}`}
function naverResults(q){q=q.trim();if(!q)return;lastQuery=q;const b=shell('인터넷');panel.classList.add('safari','naver');b.innerHTML=`<form class="naversearch" onsubmit="event.preventDefault();naverResults(this.q.value)"><b>N</b><input name="q" value="${esc(q)}"><button>${ico('search')}</button></form><div class="naverlinks">통합　이미지　지식iN　블로그　쇼핑</div><p class="webdemo">캐릭터용 검색 결과 재현 · 실시간 검색 아님</p>${(RESULTS[q]||[[q,'검색','아래에서 실제 네이버 검색 결과를 확인할 수 있습니다.']]).map(([t,s,d])=>`<article class="webresult"><small>${s}</small><h2>${esc(t)}</h2><p>${esc(d)}</p></article>`).join('')}<a class="realweb" target="_blank" rel="noopener" href="https://search.naver.com/search.naver?query=${encodeURIComponent(q)}">실제 네이버 검색 결과 보기 ↗</a>${safariBar()}`}
searchWeb=naverResults;
safariHistory=naverRecent;
const oldOpenV6=openApp;openApp=function(n){NAVSTACK=[];lastApp='';if(n==='인스타'||n==='인스타그램')igHome();else if(n==='카카오톡')kakaoChats();else oldOpenV6(n)};
const homeButton=document.createElement('button');homeButton.id='statusHome';homeButton.textContent='홈';homeButton.setAttribute('aria-label','홈으로 이동');homeButton.onclick=()=>closeApp();homeButton.hidden=true;$('.status').prepend(homeButton);
const lockObserver=new MutationObserver(()=>{if(!$('#home').hidden&&!activeApp)$('#home').animate([{opacity:.3,transform:'scale(1.09)'},{opacity:1,transform:'scale(1)'}],{duration:380,easing:'cubic-bezier(.2,.8,.2,1)'})});lockObserver.observe($('#home'),{attributes:true,attributeFilter:['hidden']});
