const snapshotBack=appBack;appBack=function(){const top=NAVSTACK.at(-1);if(top&&top.html.includes('socialrow')&&(panel.classList.contains('socialthread'))){const dm=panel.classList.contains('dmthread');NAVSTACK.pop();const keep=NAVSTACK.slice();dm?dmList():kakaoChats();NAVSTACK=keep;return}snapshotBack()};

// Canonical home transition: used by top button, bottom gesture and in-app back.
function returnHome(){clearInterval(callTimer);NAVSTACK=[];lastApp='';activeApp='';panel.hidden=true;panel.style.display='none';$('#home').hidden=false;$('#home').style.removeProperty('display');$('#pin').hidden=true;$('#lock').hidden=true;unlocked=true;$('.phone').classList.remove('in-app');$('#statusHome').hidden=true;$('#statusTime').hidden=false;$('.status').style.color='';$('.homebar').style.background='#fff';updateTime();$('#home').animate([{opacity:.5,transform:'scale(1.035)'},{opacity:1,transform:'none'}],{duration:240,easing:'ease-out'})}
closeApp=function(){if(unlocked)returnHome();else{clearInterval(callTimer);panel.hidden=true;panel.style.display='none';activeApp='';NAVSTACK=[];lastApp='';$('.phone').classList.remove('in-app');$('#statusHome').hidden=true;$('#statusTime').hidden=false;$('.status').style.color='';$('.homebar').style.background='#fff'}};
const shellV7=shell;shell=function(name,dark=false){panel.style.removeProperty('display');return shellV7(name,dark)};
$('#statusHome').onclick=function(e){e.preventDefault();e.stopPropagation();returnHome()};$('#gesture').onclick=()=>unlocked?returnHome():showPin();$('.homebar').onclick=()=>unlocked?returnHome():showPin();
EVENTS['10-4']=['아쿠아리움\n김동현 개새끼야 아쿠아리움 그만적어놔','써놓으면 가주던데'];
CONTACTS.sort((a,b)=>a.localeCompare(b,'ko'));
WEBHISTORY.forEach(r=>{if(r[0]==='아쿠아리움')r[0]='아쿠아리움 추천'});WEBHISTORY.push(['고백 방법',10,24]);
RESULTS['아쿠아리움 추천']=RESULTS['아쿠아리움'];delete RESULTS['아쿠아리움'];
RESULTS['고백 방법']=[['친구에게 마음을 전하고 싶을 때','관계 고민','상대가 편하게 대답할 수 있는 상황에서 자신의 마음을 솔직하게 전해 보세요. 상대의 답을 재촉하지 않는 것도 중요합니다.'],['고백하기 전 생각해 볼 것','대화와 관계','특별한 연출보다 진솔한 표현이 중요합니다. 상대가 거절하더라도 그 의사를 존중할 수 있는지 먼저 생각해 보세요.']];
CHATS[0]={title:'짝사랑 고민상담',messages:[['u','친구에서 연인으로 발전하려면 어떻게 해야 돼? 몇 달 전부터 좋아하는 친구가 있어. 아직 고백은 안 했고.'],['a','친구라서 더 조심스러울 수 있겠다. 두 사람은 어떤 사이야? 같이 시간을 자주 보내는 편이야?'],['u','난 한동민이고 스물셋. 한국대 실음과 2학년이야. 걔는 김동현인데 나랑 동갑이고 도예과 2학년. 다른 과 동기고 친구야.'],['a','학교에서 알게 된 동갑 친구구나. 친구에서 연인으로 가는 정해진 방법은 없지만, 단둘이 시간을 보내면서 네 마음을 조금씩 표현할 수는 있어. 다만 친절이나 장난만으로 동현이 마음을 단정하지는 않는 게 좋아.'],['u','같이 아쿠아리움도 몇 번 갔어. 내가 일정에 써놓으면 가주던데. 그냥 친구라서 같이 가주는 거겠지?'],['a','함께 가준다는 건 너와 시간을 보낼 의향이 있다는 뜻일 수 있지만, 그것만으로 연애 감정인지는 알 수 없어. “너랑 가면 좋더라. 다음에도 둘이 갈래?”처럼 부담이 적은 말부터 해 보면 어때?'],['u','자취방에서 같이 라면 먹은 적도 있는데 난 그런 것도 계속 생각나. 걔는 아무 생각 없을 수도 있잖아.'],['a','너에게 소중한 순간이었다는 건 분명해. 다만 그 순간이 동현이에게 어떤 의미였는지는 직접 듣기 전에는 알 수 없어. 상대의 마음을 추측하는 것과 네 마음을 알아주는 일은 구분해도 괜찮아.'],['u','고백했다가 친구로도 못 지낼까 봐 무서워. 아직 말 못 하겠어.'],['a','지금 당장 고백하지 않아도 돼. 네가 감당할 수 있는 속도로 다가가 봐. 나중에 마음을 전한다면 “몇 달 전부터 네가 친구 이상으로 좋아졌어. 당장 답 안 해도 돼”처럼 네 감정을 말하되 답을 재촉하지 않는 방식이 좋아. 어떤 대답이든 동현이의 선택도 존중하고.'],['u','일단 생일선물부터 생각해봐야겠다'],['a','좋아. 비싸거나 부담스러운 선물보다는 평소 동현이가 좋아한다고 말했던 것에서 골라 봐. 선물에 고백의 대답까지 기대하기보다는, 생일을 축하하는 마음 자체를 담으면 좋겠어.']]};
CHATS.push({title:'작사 과제 조언',messages:[['u','실음과 2학년인데 작사 과제 좀 도와줘. 친구를 좋아하는데 말 못 하는 내용으로 쓰고 싶어.'],['a','감정을 바로 설명하기보다 구체적인 장면으로 보여 주면 좋아. 같이 걷다가 헤어지는 길, 먹고 남은 라면 그릇처럼 화자가 계속 떠올리는 사물 하나를 중심에 놓아 봐.'],['u','아쿠아리움에서 같이 본 물고기가 자꾸 생각나. 너무 티 나려나'],['a','실제 기억을 출발점으로 삼아도 괜찮아. 다만 특정인의 이야기를 그대로 설명하기보다 유리, 푸른빛, 닿지 않는 목소리 같은 이미지로 바꾸면 가사 자체의 여백이 생겨.'],['u','후렴을 어떻게 시작하지?'],['a','예를 들면 이렇게 시작할 수 있어.\n\n유리 너머 번진 푸른 말\n네 옆에서만 삼키는 내 이름\n친구라는 얕은 물 위로\n오늘도 못 건넌 마음이 떠\n\n이건 초안이야. 네 멜로디에 맞춰 음절을 줄이고, 네가 평소 쓰는 말로 고쳐 봐.'],['u','좋다 근데 친구라는 말은 빼고 싶어. 너무 직접적이야'],['a','그러면 “늘 서 있던 얕은 물 위로”처럼 바꿔 보자. 말하지 못하는 관계를 설명하지 않고, 같은 자리에 머무는 장면으로 남기는 거야. 과제에는 직접 다듬은 표현과 작업 과정을 담아 봐.']]});
const NO_ANSWER=new Set(['엄마','아빠','한승훈','여동생']);
startCall=function(name='좋아해'){clearInterval(callTimer);callSeconds=0;const b=shell('전화',true);panel.classList.add('incall');b.innerHTML=`<div class="callperson">${esc(name)}</div><div class="callstate" id="callState">전화 거는 중…</div><div class="callportrait">${esc(name[0])}</div><div class="callcaption" id="callCaption"></div><div class="calloptions">${[['음소거','♩'],['키패드','⠿'],['스피커','◖'],['통화 추가','＋'],['FaceTime','▣'],['연락처','♙']].map(([t,i])=>`<button onclick="this.classList.toggle('enabled')"><span>${i}</span>${t}</button>`).join('')}</div><button class="endcall" aria-label="통화 종료" onclick="endCall()">${phoneIcon}</button><small class="callmock">음성 연결 없는 통화 시뮬레이션</small>`;CALLS.unshift({name,date:new Date(),missed:false});callTimer=setInterval(()=>{const state=$('#callState');if(!state){clearInterval(callTimer);return}callSeconds++;if(NO_ANSWER.has(name)){state.textContent=callSeconds<9?'연결 중…':'연결할 수 없습니다';if(callSeconds>=9){$('#callCaption').textContent='상대방이 전화를 받지 않습니다.';clearInterval(callTimer)}return}state.textContent=callSeconds<2?'연결 중…':Math.floor((callSeconds-2)/60)+':'+String((callSeconds-2)%60).padStart(2,'0');if(name==='돼지'){const lines={2:'여보세요?',5:'형 핸드폰 잃어버렸다며',8:'찾았어?',12:'... 여보세요?'};if(lines[callSeconds])$('#callCaption').textContent=lines[callSeconds]}},1000)};


const CALL_SCRIPT={'돼지':['여보세요?','아니 형 핸드폰 잃어버렸다며!!','찾았어? 찾은거야?','... 어? 여보세요?','아 폰을 주우셨다고요?','혹시 어디세요? 제가 받으러 가겠습니다'],'똥개의 일상':['여보세요?','ㅋㅋ동민이 폰 찾았냐?','... 아 주우셨다고요?','아뇨 아는 형이에요 네','그럼 제가 그쪽으로 갈테니까 나와주세요'],'상혁이형':['여보세요?','동민아 폰 찾았, 동민이 목소리가 아니네?','...','아 주우셨구나','제가 금방 그쪽으로 갈게요'],'펌킨박':['야 한동민 너 누가 폰 막 두고 다니래?','...','... 네?','아... 주우셨구나','혹시 제가 받으러 가도 될까요? 지인이라서','네 5분 뒤에 나오시면 될 것 같아요'],'좋아해':['여보세요?','한동민 너 어딘데 안와?','나 인문관 앞이라고 카톡도 안 보냐?','...','... 여보세요?','아... 폰을 주우셨다고요','혹시 제가 가도, 네?','저장명이요?','... 아','아뇨 그냥 친구인데... 일단 핸드폰부터 받을 수 있을까요?']};
startCall=function(name='좋아해'){clearInterval(callTimer);callSeconds=0;const b=shell('전화',true);panel.classList.add('incall');b.innerHTML=`<div class="callperson">${esc(name)}</div><div class="callstate" id="callState">전화 거는 중…</div><div class="callportrait">${esc(name[0])}</div><div class="callcaption" id="callCaption" aria-live="polite"></div><div class="calloptions">${[['음소거','♩'],['키패드','⠿'],['스피커','◖'],['통화 추가','＋'],['FaceTime','▣'],['연락처','♙']].map(([t,i])=>`<button onclick="this.classList.toggle('enabled')"><span>${i}</span>${t}</button>`).join('')}</div><button class="endcall" aria-label="통화 종료" onclick="endCall()">${phoneIcon}</button><small class="callmock">음성 없는 통화 시뮬레이션</small>`;CALLS.unshift({name,date:new Date(),missed:false});callTimer=setInterval(()=>{if(!$('#callState')){clearInterval(callTimer);return}callSeconds++;if(NO_ANSWER.has(name)){if(callSeconds<6)$('#callState').textContent='연결 중…';else{$('#callState').textContent='음성사서함';$('#callCaption').textContent='연결이 되지 않아 음성사서함으로 연결됩니다. 삐 소리 후 메시지를 남겨 주세요.';clearInterval(callTimer)}return}$('#callState').textContent=callSeconds<2?'연결 중…':Math.floor((callSeconds-2)/60)+':'+String((callSeconds-2)%60).padStart(2,'0');if(callSeconds>=2){const a=CALL_SCRIPT[name]||[];const i=Math.floor((callSeconds-2)/3);if(i<a.length)$('#callCaption').textContent=a[i]}},1000)};
CHATS[0]={"title":"짝사랑 고민상담","messages":[["u","친구 좋아하는 것 같은데 친구에서 연인으로 발전하려면 어떻게 해야 돼?"],["a","이미 편한 사이라면 갑자기 관계를 바꾸려 하기보다, 둘만 보내는 시간을 조금씩 늘려 보는 건 어때? 평소와는 조금 다른 관심을 표현하면서 상대의 반응도 살펴봐."],["u","둘이 밥도 자주 먹고 놀러도 가는데 걔는 그냥 친구라서 그러는 것 같아."],["a","자주 만난다는 사실만으로 마음을 단정할 수는 없어. “너랑 단둘이 있는 게 좋더라”처럼 네 마음을 조금 보여 줘도 좋아. 부담을 주지 않는 선에서 말이야."],["u","괜히 말했다가 지금처럼도 못 지내면 어떡해"],["a","그게 제일 걱정되는 거구나. 당장 고백할 필요는 없어. 네 마음과 상대의 편안함을 함께 살피면서 천천히 다가가도 괜찮아."]]};
const V8_NOW=Date.now();
function agoLabel(ts){const mins=Math.max(0,Math.floor((Date.now()-ts)/60000));if(mins<1)return '방금';if(mins<60)return mins+'분 전';if(mins<1440)return Math.floor(mins/60)+'시간 전';const d=new Date(ts);if(mins<2880)return '어제';if(mins<10080)return Math.floor(mins/1440)+'일 전';return d.toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'})}
function stampFor(label){const now=new Date();if(label==='어제 19:28'){now.setDate(now.getDate()-1);now.setHours(19,28,0,0);return +now}const match=label.match(/(\d+)\s*(분|시간|일)/);if(match)return Date.now()-Number(match[1])*({'분':60000,'시간':3600000,'일':86400000}[match[2]]);if(label.includes('어제'))return Date.now()-86400000;if(label.includes('일주일'))return Date.now()-604800000;return Date.now()}
const EXTRA_DMS=[['ceramic_room','오늘 작업실 몇 시까지 열어?',false],['yoon.zip','과제 제출했냐ㅋㅋ',false],['seoul_walks','사진 보내줘서 고마워!',true],['june.wav','다음 합주 때 보자',false],['hyeon.02','스토리 답장: 여기 어디야?',false]];
