let CURRENT_SOCIAL=null;const REPLY_TIMERS=new Map();
function avatarSeed(name){let n=0;for(const c of name)n=(n*31+c.charCodeAt(0))>>>0;return n}
function realAvatar(name){const seed=avatarSeed(name),hue=seed%360;const mark=['✿','☕','♫','🌊','☁','🌿','☀','◒'][seed%8];return `<span class="seed-avatar" style="background:hsl(${hue} 24% 83%);color:hsl(${hue} 35% 29%)">${mark}</span>`}
function socialAvatar(type,name){return type==='dm'?realAvatar(name):blank()}
socialRow=function(type,c,i){const m=c.messages.at(-1)||{text:'',ts:Date.now()};return `<button class="socialrow ${c.read?'':'unread'}" data-name="${esc(c.name)}" onclick="socialThread('${type}',${i})">${socialAvatar(type,c.name)}<div><strong>${esc(c.name)}</strong><p>${m.out?'나: ':''}${esc(m.text)}</p></div><aside><time>${agoLabel(m.ts||Date.now())}</time>${!c.read?'<span class="unreadbadge">'+(type==='kakao'?'1':'')+'</span>':''}</aside></button>`};
kHeading=function(t){return `<header class="kheading"><h1>${t} <small>⌄</small></h1><button onclick="kakaoSearch()">${ico('search')}</button><button onclick="kakaoChats()">${ico('chat')}</button><button onclick="kakaoMore()">${ico('plus')}</button></header>`};
function kakaoListFilter(unread=false){const b=kShell();CURRENT_SOCIAL=null;b.innerHTML=kHeading('채팅')+`<div class="kfilters"><button class="${unread?'':'chosen'}" onclick="kakaoChats()">전체</button><button class="${unread?'chosen':''}" onclick="kakaoListFilter(true)">안읽음 <em>${social.kakao.filter(c=>!c.read).length}</em></button><button onclick="openApp('ChatGPT')">ChatGPT</button><button onclick="kakaoSearch()">☷</button></div>`+social.kakao.map((c,i)=>unread&&c.read?'':socialRow('kakao',c,i)).join('')+kakaoNav('채팅')}
kakaoChats=function(){kakaoListFilter(false)};
kakaoMore=function(){const b=kShell();b.innerHTML=kHeading('더보기')+'<div class="kaccount"><b>한동민</b><p>계정 정보 비공개</p><div>My구독 <span>›</span></div></div><div class="moregrid">'+[['카카오멤버십','▣'],['메일','✉'],['캘린더','▣'],['톡클라우드','☁'],['이모티콘','☺'],['선물하기','♧'],['톡딜','%'],['톡타이머','◷'],['실험실','♙'],['내 결제','▤'],['공지사항','⚑'],['환경설정','⚙'],['도움말','?']].map(([n,i])=>`<button onclick="kakaoUtility('${n}')"><span>${i}</span><small>${n}</small></button>`).join('')+'</div>'+kakaoNav('더보기')};
function kakaoUtility(n){const b=kShell();b.innerHTML=kHeading(n)+'<p class="quiet">이 시안에는 연결된 외부 서비스가 없습니다.</p>'+kakaoNav('더보기')}
socialThread=function(type,i){const c=social[type][i];CURRENT_SOCIAL={type,i};c.read=true;saveSocial();const b=type==='dm'?igShell():kShell();panel.classList.add('socialthread',type==='dm'?'dmthread':'kthread');const group=type==='kakao'&&['폐급 모임','실음과 23학번 공지방'].includes(c.name);b.innerHTML=`<header class="threadhead"><button onclick="${type==='dm'?'dmList()':'kakaoChats()'}">${ico('back')}</button>${socialAvatar(type,c.name)}<strong>${esc(c.name)}${group?'<small>그룹채팅</small>':''}</strong><button onclick="${type==='kakao'&&CONTACTS.includes(c.name)?"startCall('"+c.name+"')":"this.classList.toggle('selected')"}">☎</button><span>☰</span></header><div class="socialmessages" id="socialMessages">${chatMessageHTML(type,c)}${REPLY_TIMERS.has(type+':'+i)?'<div class="typing">입력 중…</div>':''}</div><form class="socialcompose" id="socialForm"><button type="button" aria-label="첨부" onclick="this.classList.toggle('selected')">＋</button><input id="socialInput" autocomplete="off" placeholder="메시지 입력" aria-label="메시지"><button id="socialSubmit" type="submit">${type==='dm'?'보내기':'전송'}</button></form>`;const form=$('#socialForm');form.addEventListener('submit',e=>{e.preventDefault();socialSend(type,i)});$('#socialMessages').scrollTop=999999};
var chatMessageHTML;
function refreshSocial(type,i){if(!panel.hidden&&panel.classList.contains('socialthread')&&CURRENT_SOCIAL?.type===type&&CURRENT_SOCIAL.i===i){const y=$('#socialInput')?.value||'';const stack=NAVSTACK.slice();socialThread(type,i);NAVSTACK=stack;$('#socialInput').value=y}else if(!panel.hidden&&type==='kakao'&&panel.classList.contains('kakaoapp')&&!panel.classList.contains('socialthread')){const stack=NAVSTACK.slice();kakaoChats();NAVSTACK=stack}}
function contextualReply(name,text,c){const s=text.toLowerCase();if(/주웠|주우|습득|주인|분실|잃어버/.test(s)){c.foundPhone=true;return name==='좋아해'?'아… 동민이 핸드폰을 주우신 거예요? 지금 어디 계세요? 제가 받으러 갈게요.':'아 폰 주우셨구나. 알려주셔서 감사합니다. 어디로 가면 될까요?'}if(/저장명|좋아해로|좋아해라고/.test(s)&&name==='좋아해')return '…제 저장명이요? 일단 동민이 폰부터 받을 수 있을까요?';if(/고백|사귀|짝사랑|사랑/.test(s)&&name==='좋아해')return c.foundPhone?'그건 동민이랑 직접 얘기할게요. 일단 폰부터 받아도 될까요?':'갑자기 왜 그래ㅋㅋ 무슨 일 있어?';if(/어디|장소|위치/.test(s))return name==='좋아해'?'나 인문관 앞. 너 어디야?':c.foundPhone?'계신 곳 알려주시면 그쪽으로 갈게요.':'나 학교야. 무슨 일이야?';if(/인문관|정문|도서관|후문|카페|앞에|학교/.test(s))return c.foundPhone?'네, 그쪽으로 갈게요. 잠깐만 기다려 주세요.':'ㅇㅋ 거기 있어. 금방 갈게';if(/과제|팀플|마감|제출/.test(s))return name.includes('공지')?'과제 제출 일정은 공지를 다시 확인해주세요.':'나도 아직 하는 중… 제출 전에 같이 확인하자';if(/아쿠아리움|물고기|코리도라스/.test(s))return name==='좋아해'?'또 아쿠아리움?ㅋㅋ 언제 갈 건데':'아쿠아리움? 좋지. 언제?';if(/밥|라면|배고|먹/.test(s))return name==='좋아해'?'밥 아직 안 먹었어. 같이 먹을래?':'뭐 먹을 건데?';if(/잠바|옷/.test(s)&&name==='돼지')return '형 제 잠바 진짜 잊지 말고 돌려줘요ㅋㅋ';if(/고마|감사/.test(s))return c.foundPhone?'저희가 더 감사하죠. 조심히 기다려 주세요.':'뭘ㅋㅋ';if(/안녕|하이/.test(s))return '어 왔어? 무슨 일이야';if(/여기 가자|가자|만나/.test(s))return '좋지. 시간 언제 돼?';if(/ㅋㅋ|ㅎㅎ/.test(s))return 'ㅋㅋㅋㅋ 그래서 지금 어디냐고';if(/응|ㅇㅇ|알겠|네|넵|오케/.test(s))return c.foundPhone?'네, 금방 도착할게요.':'ㅇㅋ 조금 이따 봐';return c.foundPhone?'네, 확인했어요. 제가 받으러 갈게요. 위치 한 번만 알려주세요.':['어 무슨 일이야?','지금 봤어. 그래서 어떻게 할까?','잠깐만, 조금 더 말해봐'][c.messages.filter(m=>m.out).length%3]}
socialSend=function(type,i){const input=$('#socialInput');const text=input?.value.trim();if(!text)return;const c=social[type][i];c.messages.push({out:true,text,ts:Date.now(),time:clock(new Date()),delivered:false});c.read=true;input.value='';const key=type+':'+i;let pending=REPLY_TIMERS.get(key);if(pending){clearTimeout(pending);REPLY_TIMERS.delete(key)}saveSocial();REPLY_TIMERS.set(key,setTimeout(()=>{REPLY_TIMERS.delete(key);for(const m of c.messages)if(m.out)m.delivered=true;c.messages.push({out:false,text:contextualReply(c.name,text,c),ts:Date.now(),time:'방금'});c.read=!panel.hidden&&panel.classList.contains('socialthread')&&CURRENT_SOCIAL?.type===type&&CURRENT_SOCIAL.i===i;saveSocial();refreshSocial(type,i)},1300));refreshSocial(type,i)};
const STORIES=[{name:'kdhxxn_',text:'유약 색 또 다르게 나옴\n오늘도 작업실 퇴근 실패'},{name:'myeongmyeong',text:'1교시 있는 날\n왜 항상 새벽에 잠이 안 오냐'},{name:'jisoo__',text:'중간 끝나면\n진짜 놀러 갈 사람 구함'},{name:'minsuuu',text:'학식 vs 편의점\n오늘의 최대 고민'}];
igStory=function(i){const s=STORIES[Math.max(0,i-1)]||STORIES[0];const b=igShell();panel.classList.add('igstory');setAppStatus(true,true);b.innerHTML=`<div class="storyprogress"></div><header class="storytitle">${realAvatar(s.name)}<b>${i===0?'hxxnd.min':s.name}</b><small>2시간 전</small><button onclick="appBack()">×</button></header><div class="storyempty">${i===0?'기억해 둘 순간들':esc(s.text).replaceAll('\n','<br>')}</div><div class="storyreply"><input id="storyText" placeholder="메시지 보내기"><button onclick="replyStory('${s.name}')">${ico('dm')}</button></div>`};
