igComments=function(){const b=igShell();b.innerHTML='<h2 class="center">댓글 <small>3</small></h2>'+[['hxxnd.min','누구랑 갔냐','2일 전'],['myeongmyeong','와 여기 분위기 좋다','2일 전'],['minsuuu','사진 잘 나왔다ㅋㅋ','1일 전']].map(([n,t,d])=>`<div class="igcomment">${n==='hxxnd.min'?blank():realAvatar(n)}<div><b>${n} <small>${d}</small></b><p>${t}</p><small>답글 달기</small></div>${ico('heart')}</div>`).join('')+igNav()};
igProfile=function(){const b=igShell();b.innerHTML=`<header class="igprofilehead"><button onclick="appBack()">${ico('back')}</button><b>hxxnd.min</b><button onclick="igSettings()">⋮</button></header><div class="igstats">${blank('large')}<span><b>0</b>게시물</span><span><b>332</b>팔로워</span><span><b>174</b>팔로잉</span></div><p class="igbio"><b>한동민</b></p><div class="profileedit"><button onclick="igSettings()">프로필 편집</button><button onclick="igShareProfile()">프로필 공유</button></div><div class="profiletabs">${ico('grid')}${ico('profile')}</div><div class="emptypost">${ico('plus')}<h2>아직 게시물 없음</h2></div>${igNav('profile')}`};


// Keep the active conversation DOM stable while messages are sent and received.
const openThreadV9=socialThread;
socialThread=function(type,i){openThreadV9(type,i);const f=document.getElementById('socialForm');f.dataset.chatType=type;f.dataset.chatIndex=String(i);f.onsubmit=null;const btn=f.querySelector('button[type="submit"]');btn.type='button';btn.id='socialSubmit';btn.setAttribute('onclick',`event.preventDefault();event.stopPropagation();sendVisibleMessage()`);const input=f.querySelector('input');input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();sendVisibleMessage()}})};
function visibleConversation(){const f=document.getElementById('socialForm');if(!f||panel.hidden)return null;const type=f.dataset.chatType,i=Number(f.dataset.chatIndex);if(!type||!social[type]?.[i])return null;return {type,i,c:social[type][i],form:f}}
function renderVisibleMessages(){const v=visibleConversation();if(!v)return;const box=document.getElementById('socialMessages');box.innerHTML=chatMessageHTML(v.type,v.c);if(REPLY_TIMERS.has(v.type+':'+v.i)){const t=document.createElement('div');t.className='typing';t.textContent='입력 중…';box.appendChild(t)}box.scrollTop=box.scrollHeight;requestAnimationFrame(()=>box.scrollTop=box.scrollHeight)}
function sendVisibleMessage(){const v=visibleConversation();if(!v)return;const input=v.form.querySelector('input');const text=input.value.trim();if(!text)return;input.value='';const {type,i,c}=v;const key=type+':'+i;c.messages.push({out:true,text,ts:Date.now(),time:clock(new Date()),delivered:false});c.read=true;try{saveSocial()}catch(e){}renderVisibleMessages();const old=REPLY_TIMERS.get(key);if(old)clearTimeout(old);const timer=setTimeout(()=>{REPLY_TIMERS.delete(key);for(const m of c.messages)if(m.out)m.delivered=true;let reply;try{reply=contextualReply(c.name,text,c)}catch(e){reply='지금 봤어. 어디야?'}c.messages.push({out:false,text:reply,ts:Date.now(),time:clock(new Date())});const current=visibleConversation();c.read=!!current&&current.type===type&&current.i===i;try{saveSocial()}catch(e){}if(c.read)renderVisibleMessages()},1200);REPLY_TIMERS.set(key,timer);renderVisibleMessages();input.focus()}
socialSend=function(){sendVisibleMessage()};
document.addEventListener('submit',function(e){if(e.target.id==='socialForm'){e.preventDefault();e.stopImmediatePropagation();sendVisibleMessage()}},true);
// Blank avatars, as in the earlier Instagram version.
realAvatar=function(){return blank()};
STORIES.splice(3);
igHome=function(){CURRENT_SOCIAL=null;originalIGHome();const b=document.getElementById('appBody');const items=b.querySelectorAll('.stories button');items.forEach((e,i)=>{if(i>3)e.remove()});b.querySelectorAll('.postcopy small').forEach(e=>{if(e.textContent==='10월 23일')e.textContent='2일 전'})};
igStory=function(i){const idx=i===0?0:Math.max(1,Math.min(3,i));const s=STORIES[Math.max(0,idx-1)];const b=igShell();panel.classList.add('igstory');setAppStatus(true,true);b.innerHTML=`<div class="storysegments">${STORIES.map((_,n)=>`<i class="${n<idx?'seen':''}"></i>`).join('')}</div><header class="storytitle">${blank()}<b>${idx===0?'hxxnd.min':s.name}</b><small>2시간 전</small><button onclick="appBack()">×</button></header><button class="storytap left" aria-label="이전 스토리" onclick="storyMove(${idx},-1)"></button><button class="storytap right" aria-label="다음 스토리" onclick="storyMove(${idx},1)"></button><div class="storyempty">${idx===0?'기억해 둘 순간들':esc(s.text).replaceAll('\n','<br>')}</div><div class="storyreply"><input id="storyText" placeholder="메시지 보내기"><button onclick="replyStory('${s.name}')">${ico('dm')}</button></div>`};
function storyMove(i,d){if(i===0||i+d<1||i+d>3){igHome();return}const stack=NAVSTACK.slice();igStory(i+d);NAVSTACK=stack}
igComments=function(){const b=igShell();b.innerHTML='<h2 class="commenttitle">댓글 <span>3</span></h2>'+[['hxxnd.min','누구랑 갔냐','2일 전'],['myeongmyeong','@hxxnd.min 이거 너랑 간 거냐?','2일 전'],['minsuuu','사진 잘 나왔다ㅋㅋ','1일 전']].map(([n,t,d])=>`<div class="igcomment">${blank()}<div><b>${n} <small>${d}</small></b><p>${t.startsWith('@hxxnd.min')?'<button class="mention" onclick="igProfile()">@hxxnd.min</button>'+esc(t.substring(11)):esc(t)}</p><small>답글 달기</small></div>${ico('heart')}</div>`).join('')+igNav()};
function configureBackButton(){const b=document.getElementById('statusHome');b.textContent='‹ 뒤로';b.setAttribute('aria-label','뒤로가기');b.onclick=e=>{e.preventDefault();e.stopPropagation();appBack()}}
configureBackButton();const statusV9=setAppStatus;setAppStatus=function(on,dark=false){statusV9(on,dark);configureBackButton()};


