function queueReplies10(type,i,text){const c=social[type][i];c.pending10=(c.pending10||[]);c.pending10.push(text);if(c.busy10)return;function next(){if(!c.pending10.length){c.busy10=false;return}c.busy10=true;const input=c.pending10.shift();const lines=reply10(c.name,input,c).map(s=>s.replace(/\./g,''));let j=0;function emit(){if(j===lines.length){next();return}setTimeout(()=>{c.messages.forEach(m=>{if(m.out)m.delivered=true});c.messages.push({out:false,text:lines[j++],ts:Date.now(),user10:true});const v=visibleConversation();c.read=!!v&&v.c===c;saveSocial();if(c.read)renderVisibleMessages();emit()},900)}emit()}next()}
