// Photo library — add image paths to this array to extend the album.
const ALBUM_PHOTOS = [
  "assets/images/album-01.jpg",
  "assets/images/album-02.jpg",
  "assets/images/album-03.jpg",
  "assets/images/album-04.jpg",
  "assets/images/album-05.jpg",
  "assets/images/album-06.jpg",
  "assets/images/album-07.jpg",
  "assets/images/album-08.jpg",
  "assets/images/album-09.jpg",
  "assets/images/album-10.jpg"
];
function photoLibrary() {
 const body = shell('사진');
 panel.classList.add('photo-library');
 const images = [...ALBUM_PHOTOS, PHOTO];
 body.innerHTML = `<header class="album-heading"><h1>사진</h1><span>보관함</span></header><div class="album-grid">${images.map((src,i)=>`<button type="button" onclick="photoViewer(${i})" aria-label="사진 ${i+1} 크게 보기"><img loading="lazy" src="${src}" alt="사진 ${i+1}"></button>`).join('')}</div><p class="album-count">${images.length}장의 사진</p>`;
}
function photoViewer(index) {
 const images = [...ALBUM_PHOTOS, PHOTO];
 const current = Math.max(0,Math.min(images.length-1,index));
 const body = shell('사진',true);
 panel.classList.add('photo-viewer');
 body.innerHTML = `<header class="album-view-heading"><button type="button" onclick="photoLibrary()">‹ 보관함</button><span>${current+1} / ${images.length}</span></header><div class="album-full"><img src="${images[current]}" alt="사진 ${current+1}"></div><nav class="album-controls"><button type="button" onclick="photoViewer(${current-1})" ${current===0?'disabled':''}>‹ 이전</button><button type="button" onclick="photoViewer(${current+1})" ${current===images.length-1?'disabled':''}>다음 ›</button></nav>`;
 let startX=0;
 const photo=body.querySelector('.album-full');
 photo.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX;},{passive:true});
 photo.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>45)photoViewer(current+(dx<0?1:-1));},{passive:true});
}
